/* globals $ */
/**
 * @ignore
 * @throws {Error} if mediawiki message is in unexpected format.
 * @return {jQuery.Object} a list of links
 */
const getLinks = () => {
	const mobileLicense = mw.message( 'mobile-frontend-license-links' );
	const mobileMsgExists = mobileLicense.exists() && mobileLicense.text();
	const userLanguage = mw.config.get( 'wgUserLanguage' );
	if ( userLanguage === 'qqx' ) {
		// Special handling for qqx code so we can easily debug what's going on here.
		return mobileLicense.parseDom();
	} else {
		return mobileMsgExists ? mobileLicense.parseDom() : $( 'body #footer-info-copyright a' ).clone();
	}
};

/**
 * Returns the appropriate license message including links/name to
 * terms of use (if any) and license page
 *
 * @ignore
 * @return {string|undefined}
 */
const getLicenseMessage = () => {
	const $licenseLinks = getLinks();

	let licenseMsg;
	if ( $licenseLinks.length ) {
		const licensePlural = mw.language.convertNumber(
			$licenseLinks.filter( 'a' ).length
		);

		if ( $( 'body #footer-places-terms-use' ).length > 0 ) {

			const $termsLink = mw.message(
				'mobile-frontend-editor-terms-link',
				$( 'body #footer-places-terms-use a' ).attr( 'href' )
			).parseDom();
			licenseMsg = mw.message(
				'mobile-frontend-editor-licensing-with-terms',
				$termsLink,
				$licenseLinks,
				licensePlural
			).parse();
		} else {
			licenseMsg = mw.message(
				'mobile-frontend-editor-licensing',
				$licenseLinks,
				licensePlural
			).parse();
		}
	}

	return licenseMsg;
};

module.exports = getLicenseMessage;
const
	View = require( './View' ),
	util = require( './util' );

/**
 * A wrapper for creating an anchor.
 *
 * @private
 */
class Anchor extends View {
	/**
	 * @inheritdoc
	 */
	get isTemplateMode() {
		return true;
	}

	/**
	 * @mixes module:mobile.startup/View#defaults
	 * @property {Object} defaults Default options hash.
	 * @property {boolean} defaults.progressive is progressive action
	 * @property {boolean} defaults.destructive is destructive action
	 * @property {string} defaults.additionalClassNames Additional class name(s).
	 * @property {string} defaults.href url
	 * @property {string} defaults.label of anchor
	 */
	get defaults() {
		return {
			progressive: undefined,
			destructive: undefined,
			additionalClassNames: '',
			href: undefined,
			label: undefined
		};
	}

	/**
	 * @inheritdoc
	 */
	get template() {
		return util.template( `
<a {{#href}}href="{{href}}"{{/href}} class="mw-mf-anchor
	{{#progressive}} mw-mf-anchor-progressive{{/progressive}}
	{{#destructive}} mw-mf-anchor-destructive{{/destructive}}
	 {{additionalClassNames}}">{{label}}</a>
	` );
	}
}

module.exports = Anchor;
const util = require( './util' );

let browser;

/**
 * Memoize a class method. Caches the result of the method based on the
 * arguments. Instances do not share a cache.
 *
 * @private
 * @param {Function} method Method to be memoized
 * @return {Function}
 */
function memoize( method ) {
	/**
	 * Memoized version of the method
	 *
	 * @return {Function}
	 */
	const memoized = function () {
		const cache = this[ '__cache' + memoized.cacheId ] ||
			( this[ '__cache' + memoized.cacheId ] = {} ),
			key = [].join.call( arguments, '|' );
		if ( Object.prototype.hasOwnProperty.call( cache, key ) ) {
			return cache[ key ];
		}
		return ( cache[ key ] = method.apply( this, arguments ) );
	};
	memoized.cacheId = Date.now().toString() + Math.random().toString();
	return memoized;
}

/**
 * Representation of user's current browser
 *
 * @class Browser
 * @private
 */
class Browser {
	/**
	 * @param {string} userAgent the user agent of the current browser
	 * @param {jQuery.Object} $container an element to associate with the Browser object
	 */
	constructor( userAgent, $container ) {
		this.userAgent = userAgent;
		this.$el = $container;
		/**
		 * Returns whether the current browser is an ios device.
		 * FIXME: jquery.client does not support iPad detection so we cannot use it.
		 *
		 * @instance
		 * @param {number} [version] integer describing a specific version you want to test against.
		 * @return {boolean}
		 */
		this.isIos = memoize( function ( version ) {
			const ua = this.userAgent,
				ios = /ipad|iphone|ipod/i.test( ua );

			if ( ios && version ) {
				switch ( version ) {
					case 8:
					// Test UA for iOS8. Or for simulator look for Version 8
					// In the iOS simulator the OS is the host machine OS version
					// This makes testing in iOS8 simulator work as expected
						return /OS 8_/.test( ua ) || /Version\/8/.test( ua );
					case 4:
						return /OS 4_/.test( ua );
					case 5:
						return /OS 5_/.test( ua );
					default:
						return false;
				}
			} else {
				return ios;
			}
		} );
		/**
		 * Determine if a device has a widescreen.
		 *
		 * @instance
		 * @return {boolean}
		 */
		this.isWideScreen = memoize( () => {
			// Please keep in sync with MobileFrontendHooks::DEVICE_WIDTH_TABLET
			const val = 640;
			// Check viewport width to determine mobile vs tablet.
			// Note: Mobile devices held in landscape mode might receive tablet treatment.
			return window.innerWidth >= val;
		} );
		/**
		 * Whether touchstart and other touch events are supported by the current browser.
		 *
		 * @instance
		 * @return {boolean}
		 */
		this.supportsTouchEvents = memoize( () => 'ontouchstart' in window );
	}

	/**
	 * @return {Browser}
	 */
	static getSingleton() {
		let $html;
		if ( !browser ) {
			$html = util.getDocument();
			browser = new Browser( window.navigator.userAgent, $html );
		}
		return browser;
	}
}

module.exports = Browser;
const
	util = require( './util' ),
	View = require( './View' ),
	IconButton = require( './IconButton' );

/**
 * A wrapper for creating a button.
 * FIXME: T343036 This file should be combined with IconButton, all gadgets/extensions
 * using Button.js and IconButton.js will need to be updated to reflect this
 *
 * @private
 */
class Button extends View {
	/**
	 * @param {Object} options Configuration options
	 */
	constructor( options ) {
		super( options );
	}

	/**
	 * @inheritdoc
	 */
	get isTemplateMode() {
		return true;
	}

	/**
	 * @mixes module:mobile.startup/View#defaults
	 * @property {Object} defaults Default options hash.
	 * @property {string} defaults.tagName The name of the tag in which the button is wrapped.
	 * @property {boolean} defaults.progressive is progressive action
	 * @property {boolean} defaults.quiet is quiet button
	 * @property {boolean} defaults.destructive is destructive action
	 * @property {string} defaults.additionalClassNames Additional class name(s).
	 * @property {string} defaults.href url
	 * @property {string} defaults.label of button
	 * @property {boolean} defaults.disabled should only be used with tagName button
	 */
	get defaults() {
		return {
			tagName: 'a',
			disabled: false,
			progressive: undefined,
			destructive: undefined,
			quiet: undefined,
			additionalClassNames: '',
			href: undefined,
			label: undefined,
			size: 'medium'
		};
	}

	get template() {
		return util.template( '{{{_buttonHTML}}}' );
	}

	/**
	 * @inheritdoc
	 */
	preRender() {
		// Mapping existing props to Codex props used in IconButton
		let action = 'default';
		if ( this.options.progressive ) {
			action = 'progressive';
		} else if ( this.options.destructive ) {
			action = 'destructive';
		}
		let weight = this.options.quiet ? 'quiet' : 'normal';
		if ( this.options.progressive || this.options.destructive ) {
			weight = 'primary';
		}
		const options = util.extend( {
			weight,
			action,
			isIconOnly: false,
			icon: null
		}, this.options );

		this._button = new IconButton( options );
		this.options._buttonHTML = this._button.$el.get( 0 ).outerHTML;
	}
}

module.exports = Button;
const
	Drawer = require( './Drawer' ),
	util = require( './util' ),
	Button = require( './Button' ),
	Anchor = require( './Anchor' );

/**
 * Represents a query string value.
 *
 * @typedef {string|number|boolean|undefined|string[]|boolean[]} module:mobile.startup~QueryVal
 */
/**
 * Describes a combination of query string parameters.
 *
 * @typedef {Object.<string, module:mobile.startup~QueryVal>} module:mobile.startup~QueryParams
 */

/**
 * Describes a call to action drawer.
 *
 * @memberof module:mobile.startup
 * @typedef {Object} CtaOptions
 * @prop {string} [returnTo]
 * @prop {module:mobile.startup~QueryParams} [queryParams]
 * @prop {module:mobile.startup~QueryParams} [signupQueryParams]
 * @prop {Object} [progressiveButton] button options for Button element for signing in.
 *  If omitted will create a login URL.
 * @prop {Object} [actionAnchor] anchor options for Anchor element for signing up. If omitted
 *   will create a sign up URL
 * @prop {string} content text - what is the call to action?
 */

/**
 * Internal for use inside Minerva only, creates the drawer at the bottom of the screen that appears when an anonymous
 * user tries to perform an action that requires being logged in. It presents the user
 * with options to log in or sign up for a new account.
 *
 * @function CtaDrawer
 * @memberof module:mobile.startup
 * @param {module:mobile.startup.CtaOptions} options Options for drawer.
 * @return {module:mobile.startup/Drawer}
 */
function CtaDrawer( options = {} ) {
	const params = redirectParams( options.queryParams, options.returnTo );
	return new Drawer(
		util.extend( {
			children: [
				util.parseHTML( '<p>' ).text( options.content ),
				new Button( util.extend( {
					progressive: true,
					href: mw.util.getUrl( 'Special:UserLogin', params ),
					label: mw.msg( 'mobile-frontend-watchlist-cta-button-login' )
				}, options.progressiveButton ) ).$el,
				util.parseHTML( '<div>' ).addClass( 'cta-drawer__anchors' ).append(
					// Update Minerva first to avoid needing to keep this closeAnchor
					new Anchor( util.extend( {
						href: mw.util.getUrl(
							'Special:UserLogin', signUpParams( params, options.signupQueryParams )
						),
						progressive: true,
						label: mw.msg( 'mobile-frontend-watchlist-cta-button-createaccount' )
					}, options.actionAnchor ) ).$el
				)
			]
		}, options )
	);
}

/**
 * Special:UserLogin post-request redirect query parameters.
 *
 * @ignore
 * @param {QueryParams} params
 * @param {string} [redirectURL]
 * @return {QueryParams}
 */
function redirectParams( params, redirectURL ) {
	return util.extend( {
		// use wgPageName as this includes the namespace if outside Main
		returnto: redirectURL || mw.config.get( 'wgPageName' )
	}, params );
}

/**
 * Special:UserLogin account creation query parameters.
 *
 * @ignore
 * @param {...QueryParams} params
 * @return {QueryParams}
 */
function signUpParams() {
	[].push.call( arguments, { type: 'signup' } );
	const createAccountParams = util.extend.apply( util, arguments );

	// For Account Creation CTA experiment, account-creation-reading-list-cta. See T425372.
	// Add a query string indicating that the user is part of the experiment control group so we
	// can track account creations from the watchstar CTA.
	if ( mw.config.get( 'wgMFInAccountCreationCTAControl' ) ) {
		const queryString = 'readingListsAccountCreationCta=1';
		if ( createAccountParams.returntoquery ) {
			createAccountParams.returntoquery += `&${ queryString }`;
		} else {
			createAccountParams.returntoquery = queryString;
		}
	}

	return createAccountParams;
}

CtaDrawer.prototype.test = {
	redirectParams,
	signUpParams
};

module.exports = CtaDrawer;
const
	View = require( './View' ),
	util = require( './util' ),
	IconButton = require( './IconButton' );

/**
 * A {@link View} that pops up from the bottom of the screen.
 *
 * @final
 */
class Drawer extends View {
	/**
	 * @param {Object} props
	 * @param {string} [props.className] Additional CSS classes to add
	 * @param {jQuery.Element[]} [props.children] An array of elements to append to
	 * @param {Function} [props.onShow] Callback called before showing the drawer.
	 *  It receives a promise given the show process is asynchronous. This is used in
	 *  production by GrowthExperiments.
	 * @param {Function} [props.onBeforeHide] Callback called before hiding the drawer
	 */
	constructor( props ) {
		super(
			util.extend(
				{
					onBeforeHide: () => {},
					showCollapseIcon: true
				},
				props,
				{ events: util.extend( {
					'click .drawer-container__mask': () => {
						this.hide();
					},
					'click .cancel': ( ev ) => {
						ev.preventDefault();
						this.hide();
					},
					click( ev ) {
						ev.stopPropagation();
					}
				}, props.events ) }
			)
		);
	}

	initialize( props ) {
		this.drawerClassName = props.className || '';
		props.className = 'drawer-container';
		this.collapseIcon = new IconButton( {
			icon: 'expand',
			additionalClassNames: 'cancel',
			label: mw.msg( 'mobile-frontend-drawer-arrow-label' )
		} );
		// in milliseconds
		this.minHideDelay = 100;
		super.initialize( props );
	}

	/**
	 * Shows panel after a slight delay
	 *
	 * @memberof module:mobile.startup/Drawer
	 * @instance
	 * @method
	 * @return {jQuery.Promise} Resolves after onShow is called. Used in tests / GrowthExperiments.
	 */
	show() {
		const d = util.Deferred();
		this.$el.prepend( this.$mask );
		// Force redraw by asking the browser to measure the element's width
		this.$el.width();
		const $drawer = this.$el.find( '.drawer' );
		this.$mask.addClass( 'drawer-container__mask--visible' );
		if ( !$drawer.hasClass( 'visible' ) ) {
			$drawer.addClass( 'visible' );
			if ( this.options.onShow ) {
				this.options.onShow( d );
			}
			requestAnimationFrame( () => d.resolve() );
		} else {
			d.resolve();
		}
		return d.promise();
	}

	/**
	 * Hides panel
	 *
	 * @memberof module:mobile.startup/Drawer
	 * @instance
	 * @method
	 * @return {jQuery.Promise} Resolves after finished hiding. Used in tests.
	 */
	hide() {
		const d = util.Deferred();
		const $drawer = this.$el.find( '.drawer' );
		$drawer.removeClass( 'visible' );
		this.$mask.removeClass( 'drawer-container__mask--visible' );
		requestAnimationFrame( () => {
			this.options.onBeforeHide( this );
			// Should really use 'transitionend' event here, but as the
			// parent $drawer element is often detached as well, this
			// might not fire until the next show animation.
			setTimeout( () => {
				this.$mask.detach();
				d.resolve();
			}, 100 );
		} );
		return d.promise();
	}

	/**
	 * @inheritdoc
	 */
	postRender() {
		this.$mask = util.parseHTML( '<div>' ).addClass( 'drawer-container__mask' );
		const props = this.options,
			// eslint-disable-next-line mediawiki/class-doc
			$drawer = util.parseHTML( '<div>' )
				.addClass( `drawer drawer-container__drawer position-fixed ${ this.drawerClassName }`.trim() );

		if ( props.showCollapseIcon ) {
			// append the collapse icon at the top of the drawer
			$drawer.prepend( this.collapseIcon.$el );
		}

		if ( props.children ) {
			// append children
			$drawer.append( props.children );
		}
		this.$el.append( $drawer );
	}
}

module.exports = Drawer;
const
	util = require( './util' ),
	View = require( './View' );

/**
 * A wrapper for creating an icon.
 */
class Icon extends View {
	/**
	 * @param {Object} options Configuration options
	 */
	constructor( options ) {
		super( options );
	}

	/**
	 * @inheritdoc
	 */
	preRender() {
		this.options._iconClasses = this.getIconClasses();
	}

	/**
	 * Internal method that sets the correct rotation class for the icon
	 * based on the value of rotation
	 *
	 * @private
	 */
	getRotationClass() {
		let rotationClass = '';
		if ( this.options.rotation ) {
			switch ( this.options.rotation ) {
				case -180:
				case 180:
					rotationClass = 'mf-icon-rotate-flip';
					break;
				case -90:
					rotationClass = 'mf-icon-rotate-anti-clockwise';
					break;
				case 90:
					rotationClass = 'mf-icon-rotate-clockwise';
					break;
				case 0:
					break;
				default:
					throw new Error( 'Bad value for rotation given. Must be ±90, 0 or ±180.' );
			}
		}
		return rotationClass;
	}

	/**
	 * Set icon glyph class and icon type class
	 *
	 * @private
	 */
	getIconClasses() {
		const base = this.options.base;
		const icon = this.options.icon;
		const isSmall = this.options.isSmall;
		const rotationClasses = this.getRotationClass();
		const additionalClassNames = this.options.additionalClassNames;

		let classes = base + ' ';
		if ( icon ) {
			classes += this.getGlyphClassName() + ' ';
		}
		if ( isSmall ) {
			classes += 'mf-icon--small ';
		}
		if ( additionalClassNames ) {
			classes += additionalClassNames + ' ';
		}

		return classes + rotationClasses;
	}

	/**
	 * @inheritdoc
	 */
	get isTemplateMode() {
		return true;
	}

	/**
	 * @mixes module:mobile.startup/View#defaults
	 * @property {Object} defaults
	 * @property {string} defaults.base Base icon class.
	 * Defaults to 'mf-icon'.
	 * @property {string} defaults.glyphPrefix Prefix for the icon class
	 * Defaults to 'mf'.
	 * @property {string} defaults.icon Name of the icon.
	 * @property {boolean} defaults.rotation will rotate the icon by a certain number
	 *  of degrees. Must be ±90, 0 or ±180 or will throw exception.
	 * @property {boolean} defaults.isSmall If icon is small.
	 * @property {string} defaults.additionalClassNames Additional classes to be added to the icon.
	 */
	get defaults() {
		return {
			base: 'mf-icon',
			glyphPrefix: null,
			icon: '',
			rotation: 0,
			isSmall: false,
			additionalClassNames: null
		};
	}

	/**
	 * Return the full class name that is required for the icon to render
	 *
	 * @return {string}
	 */
	getClassName() {
		return this.$el.attr( 'class' );
	}

	/**
	 * Return the class that relates to the icon glyph
	 *
	 * @return {string}
	 */
	getGlyphClassName() {
		if ( this.options.glyphPrefix ) {
			return 'mf-icon-' + this.options.glyphPrefix + '-' + this.options.icon;
		}
		return 'mf-icon-' + this.options.icon;
	}

	get template() {
		return util.template(
			'<span class="{{_iconClasses}}"> </span>'
		);
	}
}

module.exports = Icon;
const
	util = require( './util' ),
	View = require( './View' ),
	Icon = require( './Icon' );

/**
 * A wrapper for creating an icon button.
 */
class IconButton extends View {
	/**
	 * @param {Object} options Configuration options
	 */
	constructor( options ) {
		if ( options.href ) {
			options.tagName = 'a';
		}
		if ( options.tagName === 'button' ) {
			options.isTypeButton = true;
		}
		super( options );
	}

	/**
	 * @inheritdoc
	 */
	preRender() {
		this.options._buttonClasses = this.getButtonClasses();
		this.options._iconHTML = '';
		if ( this.options.icon ) {
			this._icon = new Icon( {
				base: this.options.base,
				glyphPrefix: this.options.glyphPrefix,
				icon: this.options.icon,
				rotation: this.options.rotation,
				isSmall: this.options.isSmall
			} );
			this.options._iconHTML = this._icon.$el.get( 0 ).outerHTML;
		}
	}

	getButtonClasses() {
		const additionalClassNames = this.options.additionalClassNames;
		const size = this.options.size;
		const weight = this.options.weight;
		const action = this.options.action;
		const isIconOnly = this.options.isIconOnly;
		let classes = 'cdx-button ';

		if ( this.options.tagName !== 'button' ) {
			classes += 'cdx-button--fake-button cdx-button--fake-button--enabled ';
		}
		if ( size ) {
			classes += `cdx-button--size-${ size } `;
		}
		if ( weight ) {
			classes += `cdx-button--weight-${ weight } `;
		}
		if ( action ) {
			classes += `cdx-button--action-${ action } `;
		}
		if ( isIconOnly ) {
			classes += 'cdx-button--icon-only ';
		}
		return classes + additionalClassNames;
	}

	/**
	 * @inheritdoc
	 */
	get isTemplateMode() {
		return true;
	}

	/**
	 * @mixes module:mobile.startup/View#defaults
	 * @property {Object} defaults Default options hash.
	 * @property {string} defaults.tagName The name of the tag in which the button is wrapped.
	 *  Defaults to 'a' when href option present.
	 * @property {string} [defaults.href] value of href attribute,
	 *  when set tagName will default to anchor tag
	 * @property {string} defaults.additionalClassNames Additional classes to be added to the button
	 * @property {string} defaults.title Tooltip text.
	 * @property {string} defaults.size Button size.
	 * Defaults to 'large'.
	 * @property {boolean} defaults.weight Button weight.
	 * Defaults to 'quiet'.
	 * @property {boolean} defaults.action Button action.
	 * @property {boolean} defaults.isIconOnly Whether button is an icon only button
	 * Defaults to true.
	 * @property {boolean} defaults.disabled should only be used with tagName button
	 * @property {string} defaults.base String used as a base for generating class names.
	 * Defaults to 'mf-icon'.
	 * @property {string} defaults.glyphPrefix Prefix for the icon class
	 * @property {string} defaults.icon Name of the icon.
	 * @property {boolean} defaults.rotation will rotate the icon by a certain number
	 *  of degrees. Must be ±90, 0 or ±180 or will throw exception.
	 * @property {boolean} defaults.isSmall Whether the icon should be small.
	 */
	get defaults() {
		return {
			tagName: 'button',
			href: undefined,
			additionalClassNames: '',
			title: '',
			size: 'large',
			weight: 'quiet',
			action: '',
			isIconOnly: true,
			disabled: false,
			base: 'mf-icon',
			icon: '',
			rotation: 0,
			isSmall: false
		};
	}

	/**
	 * Return the full class name that is required for the icon to render
	 *
	 * @return {string}
	 */
	getClassName() {
		return this.$el.attr( 'class' );
	}

	getIcon() {
		return this._icon;
	}

	get template() {
		return util.template( `
		<{{tagName}}
			type="button"
			{{#isTypeButton}}{{#disabled}}disabled{{/disabled}}{{/isTypeButton}}
			class="{{_buttonClasses}}"
			{{#id}}id="{{id}}"{{/id}}
			{{#href}}href="{{href}}"{{/href}}
			{{#title}}title="{{title}}"{{/title}}>
				{{{_iconHTML}}}
				<span>{{label}}</span>
		</{{tagName}}>
		` );
	}
}

module.exports = IconButton;
const
	View = require( './View' ),
	header = require( './headers' ).header,
	Anchor = require( './Anchor' ),
	util = require( './util' ),
	browser = require( './Browser' ).getSingleton();

/**
 * Mobile modal window
 *
 * @uses Icon
 * @uses Button
 * @fires Overlay#hide
 */
class Overlay extends View {
	/**
	 * @param {Object} props
	 * @param {Object} props.events - custom events to be bound to the overlay.
	 * @param {boolean} [props.headerChrome] Whether the header has chrome.
	 * @param {View[]} [props.headerActions] children (usually buttons or icons)
